function AIAssistant({navigate,initialDocument='CV'}){
 const [restored]=useState(()=>{try{return JSON.parse(sessionStorage.getItem('cvora_pending_document')||'null')}catch{return null}})
 const [documentType,setDocumentType]=useState(()=>restored?.documentType||sessionStorage.getItem('cvora_document_type')||initialDocument)
 const [position,setPosition]=useState(()=>restored?.position||'Chef de projet digital')
 const [sector,setSector]=useState(()=>restored?.sector||'Gestion de projet')
 const [offer,setOffer]=useState(()=>restored?.offer||'Piloter des projets numeriques, coordonner une equipe et ameliorer l?experience client.')
 const [result,setResult]=useState(()=>restored?.result||null),[loading,setLoading]=useState(false),[message,setMessage]=useState(''),[paymentOpen,setPaymentOpen]=useState(false)
 const generate=()=>{
  if(!position.trim()){setMessage('Saisissez le poste ou domaine vise.');return}
  setLoading(true);setMessage('')
  const next=generateCareerDocument({type:documentType,position,sector,offer})
  setResult(next);setLoading(false);sessionStorage.setItem('cvora_document_type',documentType)
 }
 const requestDownload=async()=>{
  if(!result)return
  if(!supabase){setMessage('La connexion Supabase est necessaire pour payer et telecharger.');return}
  const {data:{session}}=await supabase.auth.getSession()
  if(!session){sessionStorage.setItem('cvora_pending_document',JSON.stringify({documentType,position,sector,offer,result}));navigate('auth');return}
  setPaymentOpen(true)
 }
 const downloadPaid=async reference=>{
  const {data:{user}}=await supabase.auth.getUser()
  if(!user){setMessage('Reconnectez-vous pour enregistrer votre document.');return}
  const docType=documentType==='CV'?'cv':documentType==='Lettre de motivation'?'letter':documentType.toLowerCase().includes('emploi')?'job':'stage'
  const {error}=await supabase.from('documents').insert({user_id:user.id,title:documentType+' - '+position,document_type:docType,content:{text:result.text,position,sector,offer,payment_reference:reference,payment_status:'complete'}})
  if(!error)await supabase.from('activity_events').insert({user_id:user.id,event_type:'download_pdf',metadata:{document_type:docType,title:documentType+' - '+position}})
  if(error)setMessage('Paiement confirme. Le document sera disponible dans votre historique apres synchronisation.')
  sessionStorage.removeItem('cvora_pending_document');setPaymentOpen(false);setTimeout(()=>window.print(),250)
 }
 const amount=documentType==='CV'?1500:documentType==='Lettre de motivation'?1000:500
 const docText=result?.text||''
 return <main className="ai-page"><section className="ai-hero"><div className="container"><button className="back-light" onClick={()=>navigate('home')}><ArrowLeft size={16}/> Retour</button><div className="ai-kicker"><Bot/> Assistant IA CVORA</div><h1>G&#233;n&#233;rez votre candidature en quelques secondes</h1><p>La generation locale adapte instantanement votre document au poste, au secteur et aux termes de l?offre.</p></div></section><div className="container"><AssistantQuestions/></div><div className="container ai-workspace"><div className="ai-form"><h2>D&#233;crivez votre opportunit&#233;</h2><label>Type de document<select value={documentType} onChange={e=>{setDocumentType(e.target.value);setResult(null)}}><option>CV</option><option>Lettre de motivation</option><option>Demande d?emploi</option><option>Demande de stage</option></select></label><label>Poste ou domaine vis&#233;<input value={position} onChange={e=>setPosition(e.target.value)}/></label><label>Secteur ou m&#233;tier<input value={sector} onChange={e=>setSector(e.target.value)}/></label><label>Texte de l?offre ou description<textarea rows="7" value={offer} onChange={e=>setOffer(e.target.value)} placeholder="Collez ici l?offre d?emploi ou les missions du stage"/></label>{message&&<div className="auth-message" role="status">{message}</div>}<button className="primary-btn full" onClick={generate} disabled={loading}>{loading?'G&#233;n&#233;ration?':'G&#233;n&#233;rer instantan&#233;ment'} <Sparkles size={17}/></button></div><div className="ai-result"><div className="ai-result-top"><div><span>R&#233;sultat intelligent</span><h2>{result?documentType:'Votre exemple appara&#238;tra ici'}</h2></div>{result&&<div className="score-bubble">{result.score}%</div>}</div>{result?<><div className="keyword-list">{result.keywords.map(k=><span key={k}>{k}</span>)}</div><pre className="ai-print-document">{docText}</pre><button className="primary-btn full" onClick={requestDownload}><Download size={16}/> Payer et t&#233;l&#233;charger en PDF</button><small>Le paiement n?est demand&#233; qu?au moment du t&#233;l&#233;chargement.</small></>:<div className="ai-empty"><div><Bot/></div><h3>Pr&#234;t &#224; optimiser votre candidature</h3><p>Compl&#233;tez les informations puis cliquez sur g&#233;n&#233;rer. Le r&#233;sultat apparait sans attente.</p></div>}</div></div>{paymentOpen&&<PaymentModal amount={amount} title={documentType} navigate={navigate} close={()=>setPaymentOpen(false)} onPaid={downloadPaid}/>}</main>
}
function AuthPage({navigate}){
 const [signup,setSignup]=useState(false),[name,setName]=useState(''),[email,setEmail]=useState(''),[password,setPassword]=useState(''),[showPassword,setShowPassword]=useState(false),[message,setMessage]=useState(''),[busy,setBusy]=useState(false),[providers,setProviders]=useState([])
 useEffect(()=>{let active=true;getEnabledOAuthProviders().then(enabled=>{if(active)setProviders(enabled)}).catch(()=>{});return()=>{active=false}},[])
 const submit=async()=>{if(!supabase){setMessage('Les clés publiques Supabase ne sont pas configurées.');return}setBusy(true);setMessage('');const result=signup?await supabase.auth.signUp({email,password,options:{data:{full_name:name},emailRedirectTo:window.location.origin+'/auth'}}):await supabase.auth.signInWithPassword({email,password});setBusy(false);if(result.error)setMessage(result.error.message);else if(signup&&!result.data.session)setMessage('Vérifiez votre boîte e-mail pour confirmer votre inscription.');else navigate(result.data.user?.email?.toLowerCase()===import.meta.env.VITE_ADMIN_EMAIL?.toLowerCase()?'admin':'dashboard')}
 const oauth=async provider=>{if(!supabase){setMessage('Les clés Supabase ne sont pas configurées.');return}setMessage('');const {error}=await supabase.auth.signInWithOAuth({provider,options:{redirectTo:window.location.origin+'/auth'}});if(error)setMessage(error.message)}
 const reset=async()=>{if(!email){setMessage('Saisissez votre adresse e-mail pour recevoir le lien.');return}const {error}=await supabase.auth.resetPasswordForEmail(email,{redirectTo:window.location.origin+'/auth'});setMessage(error?error.message:'Si ce compte existe, un lien de réinitialisation vient d’être envoyé.')}
 return <main className="auth-page"><div className="auth-card"><Brand/><h1>{signup?'Créer votre compte':'Bienvenue sur CVORA'}</h1><p>{signup?'Construisez une candidature remarquable.':'Accédez à vos documents et à votre espace.'}</p>{providers.map(provider=><button key={provider} className="google-btn" style={{marginTop:8}} onClick={()=>oauth(provider)}>{provider==='google'&&<b>G</b>} Continuer avec {{github:'GitHub',google:'Google',discord:'Discord',azure:'Microsoft',apple:'Apple',facebook:'Facebook',gitlab:'GitLab',linkedin_oidc:'LinkedIn'}[provider]}</button>)}{providers.length>0&&<div className="divider"><span>ou avec votre e-mail</span></div>}{signup&&<label>Nom complet<input value={name} onChange={e=>setName(e.target.value)} placeholder="Votre nom"/></label>}<label>Adresse e-mail<input type="email" value={email} onChange={e=>setEmail(e.target.value)} placeholder="nom@exemple.com" autoComplete="email"/></label><label>Mot de passe<div className="password-field"><input type={showPassword?'text':'password'} value={password} onChange={e=>setPassword(e.target.value)} placeholder="8 caracteres minimum" autoComplete={signup?'new-password':'current-password'}/><button type="button" className="password-toggle" aria-label={showPassword?'Masquer le mot de passe':'Afficher le mot de passe'} aria-pressed={showPassword} onClick={()=>setShowPassword(!showPassword)}>{showPassword?<EyeOff size={18}/>:<Eye size={18}/>}</button></div></label>{!signup&&<button className="text-btn" onClick={reset}>Mot de passe oublié ?</button>}{message&&<div className="auth-message" role="status">{message}</div>}<button className="primary-btn full" disabled={busy} onClick={submit}>{busy?'Veuillez patienter…':signup?'Créer mon compte':'Se connecter'} <ArrowRight size={17}/></button><small>{signup?'Déjà inscrit ?':'Pas encore de compte ?'} <button onClick={()=>{setSignup(!signup);setMessage('')}}>{signup?'Se connecter':'Créer un compte'}</button></small></div></main>
}
function Pricing({navigate}){return <main className="pricing-page"><section className="pricing-hero"><div className="container"><span>TARIFS SIMPLES</span><h1>Investissez dans votre prochain entretien</h1><p>Choisissez une formule ou achetez uniquement le document dont vous avez besoin.</p></div></section><div className="container pricing-body"><div className="pricing-grid"><article className="price-card"><h3>Basic</h3><p>Pour découvrir CVORA</p><div className="price">1 500 <small>FCFA</small></div><button className="outline-btn full" onClick={()=>navigate('cvs')}>Créer un CV</button><ul>{['1 modèle professionnel','Modification illimitée','Export PDF','1 CV sauvegardé'].map(x=><li key={x}><Check/> {x}</li>)}</ul></article><article className="price-card recommended"><div className="popular">RECOMMANDÉ</div><h3>Standard</h3><p>Pour plusieurs styles</p><div className="price">2 500 <small>FCFA</small></div><button className="primary-btn full" onClick={()=>navigate('cvs')}>Choisir Standard</button><ul>{['2 modèles professionnels','Personnalisation avancée','Export PDF','1 CV sauvegardé'].map(x=><li key={x}><Check/> {x}</li>)}</ul></article><article className="price-card"><h3>CVORA PRO</h3><p>Pour toute votre carrière</p><div className="price">9 500 <small>FCFA / mois</small></div><button className="outline-btn full" onClick={()=>navigate('auth')}>Passer à Pro</button><ul>{['Tous les modèles','Assistant IA','Optimisation ATS','CV illimités','Lettres et demandes'].map(x=><li key={x}><Check/> {x}</li>)}</ul></article></div><section className="quick-price"><h2>Achats ponctuels</h2><div>{[['CV personnalisé','1 500 FCFA','cvs'],['Lettre de motivation','1 000 FCFA','letters'],['Demande d’emploi','500 FCFA','jobs'],['Demande de stage','500 FCFA','stages']].map(([title,price,p])=><article key={p}><FileText/><div><b>{title}</b><small>Document personnalisé</small></div><strong>{price}</strong><button onClick={()=>navigate(p)}>Choisir</button></article>)}</div></section></div></main>}

function PricingPlans({navigate,session}){
 const [busy,setBusy]=useState(''),[message,setMessage]=useState('')
 const buy=async plan=>{if(!session){navigate('auth');return}setBusy(plan);setMessage('');try{const response=await fetch('/api/subscription-checkout',{method:'POST',headers:{'Content-Type':'application/json',Authorization:`Bearer ${session.access_token}`},body:JSON.stringify({plan})});const data=await response.json();if(!response.ok)throw Error(data.error||'Paiement indisponible.');location.assign(data.authorization_url)}catch(e){setMessage(e.message);setBusy('')}}
 const plans=[['day1','24 heures','1 500','1 CV, 1 lettre, 1 demande d’emploi et 1 demande de stage'],['day2','24 heures','2 500','2 CV, 2 lettres, 2 demandes d’emploi et 2 demandes de stage'],['month4','1 mois','9 500','4 CV, 4 lettres, 4 demandes d’emploi et 4 demandes de stage']]
 return <main className="pricing-page"><section className="pricing-hero"><div className="container"><span>ABONNEMENTS CVORA</span><h1>Choisissez votre formule</h1><p>Chaque formule ouvre les quotas indiqués pendant sa durée. Le compte à rebours commence après confirmation du paiement.</p></div></section><div className="container pricing-body"><div className="pricing-grid">{plans.map(([id,duration,price,quota],index)=><article className={'price-card'+(index===1?' recommended':'')} key={id}>{index===1&&<div className="popular">POPULAIRE</div>}<h3>{duration}</h3><p>Documents professionnels inclus</p><div className="price">{price} <small>FCFA</small></div><p className="plan-quota">{quota}</p><button className={index===1?'primary-btn full':'outline-btn full'} disabled={!!busy} onClick={()=>buy(id)}>{busy===id?'Ouverture du paiement…':'Souscrire avec NotchPay'}</button><ul>{['Accès au tableau de bord utilisateur','Suivi du temps restant','Consommation affichée dans l’historique'].map(x=><li key={x}><Check/> {x}</li>)}</ul></article>)}</div>{message&&<p role="alert" className="wallet-message">{message}</p>}</div></main>
}

function WalletPanel({session}){
 const [balance,setBalance]=useState(0),[items,setItems]=useState([]),[amount,setAmount]=useState('5000'),[busy,setBusy]=useState(false),[message,setMessage]=useState('')
 const refresh=async()=>{const [a,t]=await Promise.all([supabase.from('wallet_accounts').select('balance_xaf').eq('user_id',session.user.id).maybeSingle(),supabase.from('wallet_transactions').select('id,amount_xaf,description,created_at').eq('user_id',session.user.id).order('created_at',{ascending:false}).limit(8)]);if(a.error||t.error){setMessage('Activez le portefeuille en exécutant supabase/wallet.sql dans Supabase.');return}setBalance(Number(a.data?.balance_xaf||0));setItems(t.data||[])}
 useEffect(()=>{let active=true;const run=async()=>{await refresh();const reference=new URLSearchParams(location.search).get('wallet_payment');if(!reference)return;setBusy(true);setMessage('Vérification du paiement…');const {data:{session:current}}=await supabase.auth.getSession();const response=await fetch('/api/wallet-credit',{method:'POST',headers:{'Content-Type':'application/json',Authorization:`Bearer ${current?.access_token||''}`},body:JSON.stringify({reference})});const result=await response.json();setMessage(response.ok?`Recharge confirmée : ${Number(result.balance).toLocaleString('fr-FR')} FCFA.`:result.error||'Paiement non confirmé.');history.replaceState({},'',location.pathname);if(response.ok)await refresh();setBusy(false)};if(active)run();return()=>{active=false}},[session.user.id])
 const topup=async()=>{setBusy(true);setMessage('');try{const {data:{session:current}}=await supabase.auth.getSession();const response=await fetch('/api/wallet-topup',{method:'POST',headers:{'Content-Type':'application/json',Authorization:`Bearer ${current?.access_token||''}`},body:JSON.stringify({amount:Number(amount)})});const result=await response.json();if(!response.ok)throw new Error(result.error||'Recharge indisponible.');location.assign(result.authorization_url)}catch(e){setMessage(e.message);setBusy(false)}}
 return <article className="wallet-panel"><div className="wallet-head"><span className="wallet-icon"><Wallet/></span><div><small>PORTEFEUILLE CVORA</small><h2>{balance.toLocaleString('fr-FR')} <small>FCFA</small></h2><p>Utilisez votre solde pour régler vos documents.</p></div></div><div className="wallet-topup"><select aria-label="Montant de recharge" value={amount} onChange={e=>setAmount(e.target.value)}><option value="2000">2 000 FCFA</option><option value="5000">5 000 FCFA</option><option value="10000">10 000 FCFA</option><option value="20000">20 000 FCFA</option></select><button className="primary-btn" onClick={topup} disabled={busy}>{busy?'Vérification…':'Recharger avec NotchPay'}</button></div>{message&&<p className="wallet-message" role="status">{message}</p>}<h3>Historique</h3>{items.length?items.map(item=><div className="wallet-row" key={item.id}><span>{item.description}<small>{new Date(item.created_at).toLocaleString('fr-FR')}</small></span><b className={item.amount_xaf>0?'credit':'debit'}>{item.amount_xaf>0?'+':''}{Number(item.amount_xaf).toLocaleString('fr-FR')} FCFA</b></div>):<p className="wallet-empty">Aucune transaction.</p>}</article>
}

function SubscriptionPanel({session}){
 const [subscription,setSubscription]=useState(null),[clock,setClock]=useState(Date.now()),[message,setMessage]=useState('')
 const refresh=async()=>{const {data,error}=await supabase.rpc('cvora_subscription_status');if(!error)setSubscription(data?.active?data:null)}
 useEffect(()=>{let live=true;(async()=>{const reference=new URLSearchParams(location.search).get('subscription_payment');if(reference){setMessage('Vérification de votre abonnement…');const response=await fetch('/api/subscription-confirm',{method:'POST',headers:{'Content-Type':'application/json',Authorization:`Bearer ${session.access_token}`},body:JSON.stringify({reference})}),data=await response.json();setMessage(response.ok?'Abonnement activé.':data.error||'Abonnement non confirmé.');history.replaceState({},'',location.pathname)}if(live)await refresh()})();const timer=setInterval(()=>setClock(Date.now()),1000);const channel=supabase.channel(`subscription-${session.user.id}`).on('postgres_changes',{event:'*',schema:'public',table:'subscriptions',filter:`user_id=eq.${session.user.id}`},refresh).on('postgres_changes',{event:'*',schema:'public',table:'subscription_usage',filter:`user_id=eq.${session.user.id}`},refresh).subscribe();return()=>{live=false;clearInterval(timer);supabase.removeChannel(channel)}},[session.user.id])
 const remaining=subscription?Math.max(0,new Date(subscription.ends_at).getTime()-clock):0,format=ms=>`${Math.floor(ms/3600000)}h ${Math.floor(ms%3600000/60000)}m ${Math.floor(ms%60000/1000)}s`
 return <article className="subscription-panel"><div className="subscription-title"><div><small>MON ABONNEMENT</small><h2>{subscription?subscription.plan_code==='day1'?'Essentiel · 24 h':subscription.plan_code==='day2'?'Plus · 24 h':'Pro · 1 mois':'Aucun abonnement actif'}</h2></div>{subscription&&<strong className="countdown">{format(remaining)}</strong>}</div>{subscription?<><p>Fin prévue le {new Date(subscription.ends_at).toLocaleString('fr-FR')}</p><div className="subscription-quotas">{[['CV','cv'],['Lettres','letter'],['Demandes d’emploi','job'],['Demandes de stage','stage']].map(([label,key])=><div key={key}><span>{label}</span><b>{Math.max(0,subscription[`${key}_total`]-subscription[`${key}_used`])} / {subscription[`${key}_total`]}</b><div><i style={{width:`${Math.min(100,subscription[`${key}_used`]/Math.max(1,subscription[`${key}_total`])*100)}%`}}/></div></div>)}</div></>:<p>Souscrivez à une formule pour accéder aux quotas de documents pendant sa durée.</p>}{message&&<p role="status">{message}</p>}</article>
}

function Dashboard({navigate,session}){
 const [pendingAi]=useState(()=>Boolean(sessionStorage.getItem('cvora_pending_document')))
 const [profile,setProfile]=useState(null),[documents,setDocuments]=useState([]),[error,setError]=useState('')
 useEffect(()=>{let live=true;(async()=>{const [p,d]=await Promise.all([supabase.from('profiles').select('full_name,plan').eq('id',session.user.id).maybeSingle(),supabase.from('documents').select('id,title,document_type,created_at').eq('user_id',session.user.id).order('created_at',{ascending:false}).limit(20)]);if(!live)return;if(p.error||d.error)setError((p.error||d.error).message);setProfile(p.data);setDocuments(d.data||[])})();return()=>{live=false}},[session.user.id])
 const signOut=async()=>{await supabase.auth.signOut();navigate('home')}
 return <main className="dashboard"><aside><Brand/><nav><button className="active"><LayoutTemplate/> Mes documents</button><button onClick={signOut}><UserRound/> Déconnexion</button></nav></aside><section><header><div><span>Bonjour {profile?.full_name||session.user.user_metadata?.full_name||session.user.email} 👋</span><h1>Mes documents</h1></div><button className="primary-btn" onClick={()=>navigate('cvs')}><LayoutTemplate/> Nouveau CV</button></header>{error&&<p role="status">{error}</p>}<div className="dashboard-stats"><article><span><FileText/></span><div><b>{documents.filter(d=>d.document_type==='cv').length}</b><small>CV sauvegardés</small></div></article><article><span><Mail/></span><div><b>{documents.filter(d=>d.document_type==='letter').length}</b><small>Lettres sauvegardées</small></div></article><article><span><CreditCard/></span><div><b>{profile?.plan||'free'}</b><small>Formule</small></div></article></div><WalletPanel session={session}/><SubscriptionPanel session={session}/><h2>Documents récents</h2>{pendingAi&&<article className="pending-ai-card"><div><b>Votre document IA est pret</b><p>Reprenez le paiement et le telechargement de votre document.</p></div><button className="primary-btn" onClick={()=>navigate('ai')}>Reprendre</button></article>}{documents.length?documents.map(doc=><article className="document-row" key={doc.id}><div className="doc-thumb"/><div><b>{doc.title}</b><small>Créé le {new Date(doc.created_at).toLocaleString('fr-FR')}</small></div><button onClick={()=>navigate('editor')}>Modifier</button></article>):<p>Aucun document sauvegardé. Commencez par créer votre premier CV.</p>}</section></main>
}
function AdminGraph({daily=[]}){
 const maximum=Math.max(1,...daily.flatMap(row=>[Number(row.users||0),Number(row.documents||0)]))
 const points=key=>daily.map((row,index)=>`${daily.length<2?0:30+index*640/(daily.length-1)},${145-Number(row[key]||0)*125/maximum}`).join(' ')
 return <article className="admin-chart"><h2>Activité sur les 14 derniers jours</h2><div className="chart-legend"><span><i className="users-line"/> Inscriptions</span><span><i className="docs-line"/> Documents</span></div><svg viewBox="0 0 700 180" role="img" aria-label="Graphique des inscriptions et documents créés"><polyline className="chart-users" points={points('users')}/><polyline className="chart-docs" points={points('documents')}/></svg><div className="chart-dates"><span>{daily[0]?.day||''}</span><span>{daily[Math.floor(daily.length/2)]?.day||''}</span><span>{daily.at(-1)?.day||''}</span></div></article>
}

function AnalyticsLine({title,rows,series,currency=false}){
 const maximum=Math.max(1,...rows.flatMap(row=>series.map(item=>Number(row[item.key]||0))))
 const points=key=>rows.map((row,index)=>`${rows.length<2?0:index*680/(rows.length-1)},${150-Number(row[key]||0)*130/maximum}`).join(' ')
 return <article className="analytics-chart"><h3>{title}</h3><div className="chart-legend">{series.map(item=><span key={item.key}><i style={{background:item.color}}/>{item.label}</span>)}</div><svg viewBox="0 0 680 170" role="img" aria-label={title}>{series.map(item=><g key={item.key}><polyline points={points(item.key)} fill="none" stroke={item.color} strokeWidth="2.5" strokeLinejoin="round" strokeLinecap="round"/>{rows.map((row,index)=><circle key={`${item.key}-${row.day}`} cx={rows.length<2?0:index*680/(rows.length-1)} cy={150-Number(row[item.key]||0)*130/maximum} r="3" fill={item.color}><title>{row.day} · {item.label} : {currency?Number(row[item.key]||0).toLocaleString('fr-FR')+' FCFA':row[item.key]}</title></circle>)}</g>)}</svg><div className="chart-dates"><span>{rows[0]?.day||'—'}</span><span>{rows[Math.floor(rows.length/2)]?.day||'—'}</span><span>{rows.at(-1)?.day||'—'}</span></div></article>
}
function AnalyticsBars({title,rows,keyName='users'}){
 const max=Math.max(1,...rows.map(row=>Number(row[keyName]||0))),step=680/Math.max(1,rows.length),width=Math.max(1,step*.62)
 return <article className="analytics-chart"><h3>{title}</h3><svg viewBox="0 0 680 170" role="img" aria-label={title}>{rows.map((row,index)=>{const value=Number(row[keyName]||0),height=value*130/max,x=index*step+(step-width)/2;return <rect key={row.day} x={x} y={150-height} width={width} height={height} rx="2" fill="#1266d6"><title>{row.day} · {value} nouvelles inscriptions</title></rect>})}</svg><div className="chart-dates"><span>{rows[0]?.day||'—'}</span><span>{rows[Math.floor(rows.length/2)]?.day||'—'}</span><span>{rows.at(-1)?.day||'—'}</span></div></article>
}

function AdminAnalyticsPanel(){
 const [period,setPeriod]=useState('30d'),[grain,setGrain]=useState('day'),[from,setFrom]=useState(''),[to,setTo]=useState(''),[data,setData]=useState(null),[error,setError]=useState(''),[loading,setLoading]=useState(true)
 const load=async()=>{setLoading(true);const {data,error}=await supabase.rpc('cvora_admin_analytics',{p_period:period,p_from:from||null,p_to:to||null,p_grain:grain});if(error){setError(error.message);setData(null)}else{setError('');setData(data)}setLoading(false)}
 useEffect(()=>{load();const channel=supabase.channel('cvora-analytics-live').on('postgres_changes',{event:'*',schema:'public',table:'profiles'},load).on('postgres_changes',{event:'*',schema:'public',table:'documents'},load).on('postgres_changes',{event:'*',schema:'public',table:'activity_events'},load).on('postgres_changes',{event:'*',schema:'public',table:'payment_records'},load).on('postgres_changes',{event:'*',schema:'public',table:'subscriptions'},load).on('postgres_changes',{event:'*',schema:'public',table:'subscription_usage'},load).subscribe();return()=>supabase.removeChannel(channel)},[period,grain,from,to])
 const k=data?.kpi||{},rows=data?.series||[],d=data?.distribution||{},total=Object.values(d).reduce((sum,value)=>sum+Number(value||0),0),segments=[];let offset=0;const colors={cv:'#1266d6',letter:'#2b9d78',job:'#e49b37',stage:'#8b6be8'};for(const [key,label] of [['cv','CV'],['letter','Lettres'],['job','Demandes d’emploi'],['stage','Demandes de stage']]){const value=Number(d[key]||0),start=total?offset/total*100:0;offset+=value;segments.push(`${colors[key]} ${start}% ${total?offset/total*100:100}%`)}
 const items=[['Utilisateurs inscrits',k.users],['Actifs sur la période',k.active],['Nouveaux utilisateurs',k.newUsers],['Documents créés',k.documents],['CV créés',k.cv],['Lettres créées',k.letters],['Demandes d’emploi',k.jobs],['Demandes de stage',k.stages],['Exports PDF / Word',k.downloads],['Revenus confirmés',`${Number(k.revenue||0).toLocaleString('fr-FR')} FCFA`]]
 return <section className="analytics-panel" id="admin-activity"><header><div><small>DONNÉES AGRÉGÉES DEPUIS SUPABASE</small><h2>Analyses &amp; Statistiques</h2></div><span className="live-badge"><i/> Mise à jour en direct</span></header><div className="analytics-filters"><label>Période<select value={period} onChange={e=>setPeriod(e.target.value)}><option value="today">Aujourd’hui</option><option value="7d">7 derniers jours</option><option value="30d">30 derniers jours</option><option value="3m">3 derniers mois</option><option value="6m">6 derniers mois</option><option value="year">Cette année</option><option value="custom">Période personnalisée</option></select></label><label>Regroupement<select value={grain} onChange={e=>setGrain(e.target.value)}><option value="day">Par jour</option><option value="week">Par semaine</option><option value="month">Par mois</option></select></label>{period==='custom'&&<><label>Du<input type="date" value={from} onChange={e=>setFrom(e.target.value)}/></label><label>Au<input type="date" value={to} onChange={e=>setTo(e.target.value)}/></label></>}{data?.period&&<small>{data.period.from} — {data.period.to}</small>}</div>{loading&&!data?<p>Chargement des statistiques réelles…</p>:error?<p className="analytics-error">Statistiques indisponibles : {error}. Vérifiez que la migration analytics-subscriptions.sql a été exécutée.</p>:<><div className="analytics-kpis">{items.map(([label,value])=><article key={label}><small>{label}</small><b>{(typeof value==='number'?value: value??0).toLocaleString?.('fr-FR')??value??0}</b></article>)}</div><div className="analytics-grid"><AnalyticsBars title="Inscriptions par période" rows={rows}/><AnalyticsLine title="1 · Évolution des inscriptions" rows={rows} series={[{key:'users',label:'Nouvelles inscriptions',color:'#1266d6'}]}/><AnalyticsLine title="2 · Création des documents" rows={rows} series={[{key:'cv',label:'CV',color:'#1266d6'},{key:'letters',label:'Lettres',color:'#2b9d78'},{key:'jobs',label:'Emploi',color:'#e49b37'},{key:'stages',label:'Stage',color:'#8b6be8'}]}/><AnalyticsLine title="3 · Activité utilisateurs" rows={rows} series={[{key:'logins',label:'Connexions',color:'#1266d6'},{key:'active',label:'Actifs',color:'#2b9d78'}]}/><AnalyticsLine title="4 · Exports de documents" rows={rows} series={[{key:'downloads',label:'Exports consignés',color:'#e49b37'}]}/><AnalyticsLine title="5 · Revenus des paiements confirmés" rows={rows} series={[{key:'revenue',label:'Revenus XAF',color:'#2b9d78'}]} currency/><article className="analytics-chart"><h3>6 · Répartition des documents</h3><div className="distribution-row"><div className="donut-chart" style={{background:`conic-gradient(${segments.join(',')})`}}><span>{total}</span></div><div>{[['cv','CV'],['letter','Lettres'],['job','Demandes d’emploi'],['stage','Demandes de stage']].map(([key,label])=><p key={key}><i style={{background:colors[key]}}/>{label}<b>{Number(d[key]||0)}</b></p>)}</div></div></article></div><article className="subscription-tracking"><h3>Suivi des abonnements et de leur consommation</h3>{data.subscriptions?.length?data.subscriptions.map(sub=><div className="subscription-track" key={sub.id}><div className="subscription-track-head"><span><b>{sub.email||'Compte supprimé'}</b><small>{sub.plan_code} · début {new Date(sub.starts_at).toLocaleString('fr-FR')} · fin {new Date(sub.ends_at).toLocaleString('fr-FR')}</small></span><b>{sub.status==='active'&&new Date(sub.ends_at)>new Date()?'Actif':sub.status}</b></div><div className="track-quotas">{[['CV','cv'],['Lettres','letter'],['Emploi','job'],['Stage','stage']].map(([label,key])=><span key={key}>{label} {sub[`${key}_used`]}/{sub[`${key}_total`]}<i><b style={{width:`${Math.min(100,sub[`${key}_used`]/Math.max(1,sub[`${key}_total`])*100)}%`}}/></i></span>)}</div>{sub.usage?.length>0&&<small className="usage-timeline">{sub.usage.map(u=>u.document_type+' · '+new Date(u.created_at).toLocaleString('fr-FR')).join('  •  ')}</small>}</div>):<p>Aucun abonnement réel enregistré sur cette période.</p>}</article></>}</section>
}

function Admin({navigate, session}) {
 const [data,setData]=useState(null),[error,setError]=useState(''),[loading,setLoading]=useState(true)
 useEffect(()=>{let live=true;const refresh=async()=>{const {data,error}=await supabase.rpc('cvora_admin_dashboard');if(!live)return;if(error)setError(error.message);else{setData(data);setError('')}setLoading(false)};refresh();const channel=supabase.channel('cvora-admin-live').on('postgres_changes',{event:'*',schema:'public',table:'profiles'},refresh).on('postgres_changes',{event:'*',schema:'public',table:'documents'},refresh).on('postgres_changes',{event:'*',schema:'public',table:'activity_events'},refresh).subscribe();return()=>{live=false;supabase.removeChannel(channel)}},[])
 const signOut=async()=>{await supabase.auth.signOut();navigate('home')}
 if(loading)return <main className="admin-page"><section><h1>Chargement du tableau de bord…</h1></section></main>
 if(error)return <main className="admin-page"><section><h1>Accès administrateur indisponible</h1><p>{error.includes('42501')?'Cette adresse n’est pas autorisée à consulter ce tableau de bord.':error}</p><button className="outline-btn" onClick={()=>navigate('home')}>Retour à l’accueil</button></section></main>
 const users=data?.recentUsers||[]
 return <main className="admin-page"><aside><Brand/><nav><button className="active"><BarChart3/> Vue générale</button><button onClick={()=>document.getElementById('admin-users')?.scrollIntoView({behavior:'smooth'})}><Users/> Utilisateurs</button><button onClick={()=>document.getElementById('admin-activity')?.scrollIntoView({behavior:'smooth'})}><FileText/> Activité</button><button onClick={signOut}><UserRound/> Déconnexion</button></nav></aside><section><header><div><small>Connecté : {session?.user?.email}</small><h1>Tableau de bord administrateur</h1></div><div className="live-badge"><i/> Données en direct</div></header><div className="admin-stats"><article><small>Utilisateurs inscrits</small><b>{Number(data?.users||0).toLocaleString('fr-FR')}</b></article><article><small>Actifs dans les 5 dernières minutes</small><b>{Number(data?.online||0).toLocaleString('fr-FR')}</b></article><article><small>Documents créés</small><b>{Number(data?.documents||0).toLocaleString('fr-FR')}</b></article><article><small>Candidatures enregistrées</small><b>{Number(data?.applications||0).toLocaleString('fr-FR')}</b></article></div><AdminGraph daily={data?.dailyStats||[]}/><AdminAnalyticsPanel/><div className="admin-grid"><article id="admin-users"><h2>Utilisateurs récents (100 max.)</h2><div className="user-table"><div className="table-head"><b>Utilisateur</b><b>Plan</b><b>Documents</b><b>Inscription</b></div>{users.length?users.map(u=><div className="table-row" key={u.id}><span><i>{(u.name||u.email||'?')[0].toUpperCase()}</i><p><b>{u.name||'Sans nom'}</b><small>{u.email}</small></p></span><b>{u.plan||'free'}</b><b>{u.documents}</b><em>{u.last_seen?`Vu ${new Date(u.last_seen).toLocaleString('fr-FR')}`:'Jamais connecté'}</em></div>):<p>Aucun utilisateur pour le moment.</p>}</div></article><article className="activity-card" id="admin-activity-log"><h2>Activité récente</h2>{data?.recentActivity?.length?data.recentActivity.map((event,i)=><p key={`${event.created_at}-${i}`}><b>{event.event_type}</b><br/><small>{event.user_email||'Utilisateur supprimé'} · {new Date(event.created_at).toLocaleString('fr-FR')}</small></p>):<p>Aucune activité enregistrée.</p>}</article></div></section></main>
}
function pageFromPath(){const path=window.location.pathname.replace(/\/+$/,'')||'/';return ({'/':'home','/auth':'auth','/dashboard':'dashboard','/admin':'admin','/cvs':'cvs','/letters':'letters','/jobs':'jobs','/stages':'stages','/pricing':'pricing','/ai':'ai'})[path]||'home'}
function pathFromPage(page){return ({home:'/',auth:'/auth',dashboard:'/dashboard',admin:'/admin',cvs:'/cvs',letters:'/letters',jobs:'/jobs',stages:'/stages',pricing:'/pricing',ai:'/ai'})[page]||'/'}
export default function PlatformApp() {
 const [page,setPage]=useState(pageFromPath),[template,setTemplate]=useState(cvTemplates[0]),[session,setSession]=useState(null),[authReady,setAuthReady]=useState(!supabase)
 useEffect(()=>{if(!supabase)return;let alive=true;supabase.auth.getSession().then(({data})=>{if(!alive)return;setSession(data.session);setAuthReady(true);if(data.session){supabase.rpc('cvora_touch_last_seen');if(localStorage.getItem('cvora_cv_draft')){try{const draft=JSON.parse(localStorage.getItem('cvora_cv_draft'));if(draft.cv){window.dispatchEvent(new CustomEvent('cvora:restore-draft',{detail:draft}))}}catch{localStorage.removeItem('cvora_cv_draft')}}}if(pageFromPath()==='auth'&&data.session)navigate(data.session.user.email?.toLowerCase()===import.meta.env.VITE_ADMIN_EMAIL?.toLowerCase()?'admin':'dashboard')});const {data:{subscription}}=supabase.auth.onAuthStateChange((_event,next)=>{setSession(next);setAuthReady(true);if(next&&_event==='SIGNED_IN'){supabase.rpc('cvora_touch_last_seen');supabase.from('activity_events').insert({user_id:next.user.id,event_type:'login'}).then(()=>{})}if(next&&pageFromPath()==='auth')setTimeout(()=>navigate(next.user.email?.toLowerCase()===import.meta.env.VITE_ADMIN_EMAIL?.toLowerCase()?'admin':'dashboard'),0)});return()=>{alive=false;subscription.unsubscribe()}},[])
 useEffect(()=>{const pop=()=>setPage(pageFromPath());window.addEventListener('popstate',pop);return()=>window.removeEventListener('popstate',pop)},[])
 useEffect(()=>{window.scrollTo({top:0,behavior:'instant'})},[page])
 useEffect(()=>{if(!session||!supabase)return;const timer=setInterval(()=>supabase.rpc('cvora_touch_last_seen'),60000);return()=>clearInterval(timer)},[session?.user?.id])
 function navigate(next){if(['dashboard','admin'].includes(next)&&!session){next='auth'}else if(next==='admin'&&session?.user?.email?.toLowerCase()!==import.meta.env.VITE_ADMIN_EMAIL?.toLowerCase()){next='dashboard'}window.history.pushState({},'',pathFromPage(next));setPage(next)}
 useEffect(()=>{if(!authReady)return;if(['dashboard','admin'].includes(page)&&!session)navigate('auth');else if(page==='admin'&&session?.user?.email?.toLowerCase()!==import.meta.env.VITE_ADMIN_EMAIL?.toLowerCase())navigate('dashboard')},[page,session,authReady])
 const noShell=['editor','auth','dashboard','admin'].includes(page)
 return <>{!noShell&&<Header page={page} navigate={navigate} session={session}/>} {page==='home'&&<Home navigate={navigate}/>} {page==='cvs'&&<CvCatalog navigate={navigate} setTemplate={setTemplate}/>} {page==='letters'&&<DocumentCatalog navigate={navigate} type="letters"/>} {page==='jobs'&&<DocumentCatalog navigate={navigate} type="jobs"/>} {page==='stages'&&<DocumentCatalog navigate={navigate} type="stages"/>} {page==='ai'&&<AIAssistant navigate={navigate} initialDocument={page==='ai'?undefined:'CV'}/>} {page==='pricing'&&<PricingPlans navigate={navigate} session={session}/>} {page==='auth'&&<AuthPage navigate={navigate}/>} {page==='editor'&&<CVEditor template={template} navigate={navigate} session={session}/>} {page==='dashboard'&&session&&<Dashboard navigate={navigate} session={session}/>} {page==='admin'&&session&&session.user.email?.toLowerCase()===import.meta.env.VITE_ADMIN_EMAIL?.toLowerCase()&&<Admin navigate={navigate} session={session}/>} {!noShell&&<Footer/>}{!noShell&&<a className="whatsapp-float" href="https://wa.me/237680409437" target="_blank" rel="noreferrer"><img src="/logowhatsapp.jpeg" alt="WhatsApp"/><span>Besoin d’aide ?</span></a>}</>
}






